fn append_array(mut a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Pre-allocate enough space for all elements of a and b
    a.reserve(b.len());
    // Move all elements of b into the end of a
    a.extend(b);
    a
}

